#!/usr/bin/env python3
"""Build static prompt factory; standard library, no network or deployment."""
import html
import json
import re
from pathlib import Path
from prompt_factory import catalog, generate

ROOT = Path(__file__).resolve().parents[1]
DUMMY = {'projeto': '__CADU_TARGET__', 'pedido': '__CADU_REQUEST__', 'estudo_anexado': False}

def build():
    routes = catalog()['modes']
    out = ROOT / 'docs/fabrica'
    out.mkdir(parents=True, exist_ok=True)
    data = {'dummy': DUMMY, 'routes': {}}
    options = []
    for mode, route in routes.items():
        data['routes'][mode] = {**route, 'template': generate(mode, DUMMY['projeto'], DUMMY['pedido'])}
        options.append(f'<option value="{html.escape(mode)}">{html.escape(route["label"])}</option>')
    (out / 'routes.json').write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    text = {
        'pt': {'html':'pt-BR','title':'Fábrica de prompts | Engenharia Cadu','back':'← Engenharia Cadu','eyebrow':'UM PEDIDO · UM CAMINHO · CONTEXTO RECUPERÁVEL','headline':'Escolha o caminho. Gere o comando.','intro':'A fábrica organiza sua próxima ação antes que o agente comece. Escolha a situação que melhor descreve o projeto, informe o resultado desejado e copie um comando pronto para continuar sem repetir o contexto.','steps':'Como funciona','step1':'1. Identifique o momento do projeto','step2':'2. Descreva o resultado desejado','step3':'3. Copie e cole na conversa do agente','custom':'PERSONALIZAR','need':'O que você precisa?','project':'Projeto','project_ph':'Nome, caminho ou repositório','result':'Resultado desejado','result_ph':'Ex.: reconciliar o estudo novo e retomar a implementação','attach':'Vou anexar um estudo à conversa','note':'A fábrica gera o comando. A execução acontece no agente, conforme as autorizações reais do projeto.','download1':'Baixar comando completo para assumir projeto','download2':'Baixar comando completo para reestruturar','generated':'COMANDO PRONTO','copy':'Copiar comando','learn':'Entender o método','noscript':'A personalização requer JavaScript. O comando padrão e os downloads continuam disponíveis.','paths':[('Assumir projeto','Estudos, anexos ou código já existem. Reconcilie o estado real e continue com segurança.','Começar por aqui'),('Reestruturar','O projeto está confuso, incompleto ou fora do método. Diagnostique e corrija a rota.','Corrigir o caminho'),('Retomar checkpoint','Existe um estado salvo. Continue do próximo lote registrado, sem refazer o que já foi concluído.','Retomar agora'),('Escolha automática','Você sabe o resultado, mas não sabe qual procedimento usar. A fábrica seleciona a rota suficiente.','Escolher por mim')]},
        'en': {'html':'en','title':'Prompt factory | Cadu Engineering','back':'← Cadu Engineering','eyebrow':'ONE REQUEST · ONE PATH · RECOVERABLE CONTEXT','headline':'Choose the path. Generate the command.','intro':'The factory organizes the next action before the agent starts. Choose the situation that best describes the project, state the desired outcome, and copy a ready command without repeating context.','steps':'How it works','step1':'1. Identify the project moment','step2':'2. Describe the desired outcome','step3':'3. Copy and paste into the agent conversation','custom':'CUSTOMIZE','need':'What do you need?','project':'Project','project_ph':'Name, path or repository','result':'Desired outcome','result_ph':'Example: reconcile the new study and resume implementation','attach':'I will attach a study to the conversation','note':'The factory generates the command. Execution happens in the agent according to the project permissions.','download1':'Download full assume-project command','download2':'Download full restructure-project command','generated':'READY COMMAND','copy':'Copy command','learn':'Understand the method','noscript':'Customization requires JavaScript. The default command and downloads remain available.','paths':[('Assume project','Studies, attachments or existing code are available. Reconcile the real state and continue safely.','Start here'),('Restructure','The project is unclear, incomplete or off method. Diagnose and correct the route.','Correct the route'),('Resume checkpoint','A saved state exists. Continue from the next recorded batch without repeating completed work.','Resume now'),('Automatic choice','You know the outcome but not which procedure to use. The factory selects the sufficient route.','Choose for me')]},
        'es': {'html':'es','title':'Fábrica de prompts | Ingeniería Cadu','back':'← Ingeniería Cadu','eyebrow':'UNA SOLICITUD · UN CAMINO · CONTEXTO RECUPERABLE','headline':'Elija el camino. Genere el comando.','intro':'La fábrica organiza la próxima acción antes de que el agente comience. Elija la situación del proyecto, describa el resultado y copie un comando listo sin repetir el contexto.','steps':'Cómo funciona','step1':'1. Identifique el momento del proyecto','step2':'2. Describa el resultado deseado','step3':'3. Copie y pegue en la conversación del agente','custom':'PERSONALIZAR','need':'¿Qué necesita?','project':'Proyecto','project_ph':'Nombre, ruta o repositorio','result':'Resultado deseado','result_ph':'Ejemplo: reconciliar el estudio nuevo y retomar la implementación','attach':'Adjuntaré un estudio a la conversación','note':'La fábrica genera el comando. La ejecución ocurre en el agente según las autorizaciones reales del proyecto.','download1':'Descargar comando completo para asumir proyecto','download2':'Descargar comando completo para reestructurar','generated':'COMANDO LISTO','copy':'Copiar comando','learn':'Entender el método','noscript':'La personalización requiere JavaScript. El comando predeterminado y las descargas siguen disponibles.','paths':[('Asumir proyecto','Hay estudios, anexos o código existente. Reconcilie el estado real y continúe con seguridad.','Comenzar aquí'),('Reestructurar','El proyecto está confuso, incompleto o fuera del método. Diagnostique y corrija la ruta.','Corregir la ruta'),('Retomar checkpoint','Existe un estado guardado. Continúe desde el próximo lote registrado sin repetir lo concluido.','Retomar ahora'),('Elección automática','Sabe el resultado, pero no qué procedimiento usar. La fábrica selecciona la ruta suficiente.','Elegir por mí')]}
    }
    def make_page(lang):
        t=text[lang]; default=html.escape(generate()); localized_options=''.join(f'<option value="{html.escape(mode)}">{html.escape(t["paths"][{"assumir":0,"reestruturar":1,"retomar":2,"auto":3}.get(mode,3)][0] if mode in {"assumir","reestruturar","retomar","auto"} else route["label"])}</option>' for mode,route in routes.items())
        page=f'''<!doctype html><html lang="{t['html']}" data-language="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t['title']}</title><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'none"><link rel="stylesheet" href="../assets/factory.css"><script defer src="../assets/factory.js"></script></head><body><main><nav class="topbar"><a href="../index.html">{t['back']}</a><span class="languages"><a href="index.html" {'aria-current="page"' if lang=='pt' else ''}>PT</a><a href="index.en.html" {'aria-current="page"' if lang=='en' else ''}>EN</a><a href="index.es.html" {'aria-current="page"' if lang=='es' else ''}>ES</a></span></nav><p class="eyebrow">{t['eyebrow']}</p><h1>{t['headline']}</h1><p class="intro">{t['intro']}</p><section class="how"><p class="section-kicker">{t['steps']}</p><div><strong>{t['step1']}</strong><strong>{t['step2']}</strong><strong>{t['step3']}</strong></div></section><section class="pathways" aria-label="{t['steps']}">{''.join(f'<div class="pathway{' pathway-primary' if i==3 else ''}"><span class="path-number">0{i+1}</span><h2>{p[0]}</h2><p>{p[1]}</p><button class="path-button" type="button" data-mode="{["assumir","reestruturar","retomar","auto"][i]}">{p[2]}</button></div>' for i,p in enumerate(t['paths']))}</section><div class="grid"><section aria-label="{t['custom']}"><p class="section-kicker">{t['custom']}</p><label for="mode">{t['need']}</label><select id="mode">{localized_options}</select><label for="target">{t['project']}</label><input id="target" placeholder="{t['project_ph']}"><label for="request">{t['result']}</label><textarea id="request" rows="5" placeholder="{t['result_ph']}"></textarea><label class="check"><input id="attachment" type="checkbox"> {t['attach']}</label><p class="small">{t['note']}</p><p><a href="../comandos/ASSUMIR_PROJETO.txt" download>{t['download1']}</a></p><p><a href="../comandos/REESTRUTURAR_PROJETO.txt" download>{t['download2']}</a></p></section><section aria-label="{t['generated']}"><p class="section-kicker">{t['generated']}</p><textarea id="output" rows="21" readonly>{default}</textarea><button id="copy" type="button">{t['copy']}</button><p id="status" role="status" aria-live="polite"></p></section></div><noscript><p>{t['noscript']}</p></noscript><p class="small">Método 2.3 · <a href="https://github.com/carlosemox/engenharia-cadu/blob/main/fabrica/README.md">{t['learn']}</a></p></main></body></html>'''
        return page
    for lang,filename in (('pt','index.html'),('en','index.en.html'),('es','index.es.html')):
        (out/filename).write_text(make_page(lang),encoding='utf-8')
    for name in ('ASSUMIR_PROJETO', 'REESTRUTURAR_PROJETO'):
        source = (ROOT / f'comandos/{name}.md').read_text(encoding='utf-8')
        body = re.search(r'## Comando completo\n```text\n([\s\S]*?)\n```', source).group(1)
        (ROOT / f'docs/comandos/{name}.txt').write_text(body+'\n', encoding='utf-8')
    mirror = (ROOT/'read.md').read_text(encoding='utf-8')
    def canonical_link(match):
        url = match.group(1)
        if ':' in url or url.startswith(('#', '//')):
            return match.group(0)
        return '](https://github.com/carlosemox/engenharia-cadu/blob/main/'+url+')'
    mirror = re.sub(r'\]\(([^\s)]+)\)', canonical_link, mirror)
    (ROOT / 'docs/read.md').write_text(mirror, encoding='utf-8')
    print('Fábrica e dois comandos completos gerados; nenhum projeto executado.')

if __name__ == '__main__':
    build()
